package set_dep

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "set_dep"
	command.Identifiers = []string{"set-dep"}
	command.Category = "Deps System"
	command.Help = "Moves one remote dep to another version of its module"
	command.LongDescription = "Re-copies the remote repo's sandbox/api into sandbox/deps/<dep>/ at the given version and regenerates the shim that converts it, then calls build. The module comes from the shim's own adapter.yaml."
	command.Examples = []string{"set-dep mathlib --version v1.3.0"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "version",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the module version to copy the contract from",
			Examples:    []string{"set-dep mathlib --version v1.3.0"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--version"},
		},
		{
			Id:          "remote-available",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the available of the remote repo the regenerated shim builds its sandbox from",
			Examples:    []string{"set-dep mathlib --version v1.3.0 --remote-available standard"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--remote-available"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"set-dep mathlib --version v1.3.0 --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"set-dep mathlib --version v1.3.0 -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "dep",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the remote dep to move",
			Examples:    []string{"set-dep mathlib --version v1.3.0"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
